// One owner for the browser title across route changes and closed panels.
import { useLayoutEffect } from "react";
import { useEdition } from "./data";
import { PAPER_NAMES } from "./papers";
import type { Route } from "./router";
import site from "@instance/site";
import { SITE_NAME } from "./siteName";

/** The edition's title, as the front page and index.html give it. */
export const EDITION_TITLE = site.editionTitle;

export function PageTitle({ route }: { route: Route }) {
  const { graph } = useEdition();
  const label = "node" in route && route.node ? graph.nodes.get(route.node)?.label : undefined;
  let title: string;
  switch (route.view) {
    case "home":
      title = EDITION_TITLE;
      break;
    case "map":
      title = route.edge ? "Argument step" : label ?? "Argument map";
      break;
    case "read":
      title = PAPER_NAMES[route.stage].short;
      break;
    case "checks":
      title = label ? `What ran on ${label}` : "What ran";
      break;
    case "compare":
      title = label ? `Compare: ${label}` : "Compare side by side";
      break;
    case "lean":
      // A name in the address may not exist, so LeanPage names the tab once it has checked.
      title = route.index ? "Declarations linked to the papers" : "Lean index";
      break;
    case "about":
      title = "About";
      break;
    case "search":
      title = route.q.trim() ? `Search: ${route.q.trim()}` : "Search";
      break;
    case "missing":
      title = "Page not found";
      break;
  }
  useLayoutEffect(() => {
    // The front page carries the edition's own title, as a search result or a tab names it.
    document.title = route.view === "home" ? title : `${title} · ${SITE_NAME}`;
  }, [title, route.view]);
  return null;
}
